const fs = require('fs');
const path = require('path');

const now = new Date();
const start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0, 0);
const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 1, 0, 0, 0, 0);

return items.filter((item) => {
  const json = item.json || {};
  const bin = (item.binary && item.binary.data) || {};
  const directory = json.directory || bin.directory || '';
  const fileName = json.fileName || bin.fileName || '';
  if (!directory || !fileName) return false;
  const filePath = path.join(directory, fileName);
  try {
    const stat = fs.statSync(filePath);
    return stat.mtimeMs >= start.getTime() && stat.mtimeMs < end.getTime();
  } catch (e) {
    return false;
  }
});
